-- EXEC.md EXEC-W wave B / EXEC-Y Fase 4 (M119; go 2026-10-09 "lanjut fase 4 dan 5 dulu"): the tool contracts the code now offers.
-- run_python v6: a table the session emitted is loaded by output_id or name from the next
-- run_python (label NOT_RELEASED until released), and save_table / load_table keep working tables
-- by name within the session's working_table_bytes, never released or cited (M119: GT1 typed the
-- ids of its own tables and load_output refused them).
-- Inactive like every market-ai-orc row; input schema and purpose from the code, every other column copied from the
-- previous version.
-- GENERATED by scripts/generate_tool_catalog_migration.py; market-ai-orc tests/test_data_need_tool.py fails on
-- drift. Do not edit by hand.
BEGIN;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '1min';

DO $preflight$
BEGIN
    IF (SELECT count(*) FROM public."Tool_Catalog" WHERE (tool_name, version) IN (('run_python', 'v5'))) <> 1 THEN
        RAISE EXCEPTION 'Expected the previous tool versions (''run_python'', ''v5'')';
    END IF;
    IF EXISTS (SELECT 1 FROM public."Tool_Catalog" WHERE (tool_name = 'run_python' AND version = 'v6')) THEN
        RAISE EXCEPTION 'The M119 working tables tool versions are already registered';
    END IF;
END
$preflight$;

INSERT INTO public."Tool_Catalog" (
    tool_name, tool_family, tool_type, purpose, input_schema, output_schema,
    execution_type, handler_name, default_output_rows, max_output_rows,
    max_input_rows, max_tickers, max_date_range_days, max_estimated_rows,
    timeout_seconds, max_output_bytes, max_llm_result_rows,
    max_llm_result_bytes, max_llm_result_tokens,
    requires_analytics_worker, requires_feature_catalog, requires_data_readiness,
    tool_specific_limits, version, is_active
)
SELECT tool_name, tool_family, tool_type, next.purpose, next.input_schema::jsonb, output_schema,
       execution_type, handler_name, default_output_rows, max_output_rows,
       max_input_rows, max_tickers, max_date_range_days, max_estimated_rows,
       timeout_seconds, max_output_bytes, max_llm_result_rows,
       max_llm_result_bytes, max_llm_result_tokens,
       requires_analytics_worker, requires_feature_catalog, requires_data_readiness,
       tool_specific_limits || '{"design":"EXEC.md EXEC-W wave B B2; ERRORS_AND_SOLUTIONS.md M119","registry_state":"registered from code (market-ai-orc) under the dev flags, inactive here","working_tables":"PY_SANDBOX_WORKING_TABLE_BYTES, default half of the session''s intermediate disk; a table above the quota is refused and nothing is written"}'::jsonb, next.version, false
FROM public."Tool_Catalog" AS previous
JOIN (VALUES
    ('run_python', 'v5', 'v6', '{"additionalProperties":false,"properties":{"code":{"description":"Python to run in the session''s namespace.","type":"string"},"complete":{"anyOf":[{"type":"boolean"},{"type":"null"}],"description":"true on the last call: when this code runs OK the backend calls complete_analysis at once and returns its result with this one; null or false keeps the session open."},"session_id":{"type":"string"}},"required":["session_id","code","complete"],"type":"object"}',
     'Run Python in the session. pandas as pd, numpy as np and saniti with all its helpers are pre-bound; TA-Lib (import talib), scipy, statsmodels, polars, duckdb and matplotlib are available. Read data only through the helpers: load(request) returns a whole dataset (every row of every range, including warm-up history), load_range(request, range_id, include_buffers=False) one approved range (also saniti.range; plain range() is Python''s built-in), in_period(frame, request) the mask of the rows inside the approved ranges (count and summarise only those; warm-up rows feed indicators), sql(query) DuckDB over one view per logical name, join(relationship_id) the approved relationship with its point-in-time semantics, quality(request) the Data Quality Manifest, requests() and manifest() the bundle, resample(frame, request) the catalog rules. Reads outside the helpers count as not processed. Each dataset of the session shows materialize: DIRECT (load() may read it whole) or AGGREGATE_FIRST (reduce it in sql() first, e.g. GROUP BY its entity and date columns): load(), range() and sql() refuse a pandas frame larger than the session''s frame budget with MaterializationLimitExceeded, before anything is loaded; the session, its data and variables stay, so revise the code, never the data need. Write any logic you need; define functions and call them later. Emit results with emit_table(name, frame), emit_json(name, value), emit_text(name, text), emit_chart(figure, name, title), emit_file(name, data, format); emit_table and emit_json take units={column: ''FRACTION'' | ''PERCENT'' | ''P_VALUE''} for every column holding a share or a return as a decimal, a value already in percent, or a p-value, so the answer''s value references are formatted by the data''s unit, and definition={''filters'': [{''column'', ''operator'', ''value''}], ''period'': {''start'', ''end''}, ''entities'', ''thresholds'', ''notes''}: how the result was made beyond the data request (filters in the data need''s operators EQ, NEQ, GT, GTE, LT, LTE, IN, NOT_IN, BETWEEN, IS_NULL, IS_NOT_NULL; {} when the code applied none), which later turns read instead of guessing; complete_analysis does not release a table or JSON without one. A table of an earlier result opened with load_output carries its definition in .attrs; a table this session emitted is loaded the same way, by output_id or name, from the next run_python (label NOT_RELEASED until released), and save_table(name, frame) / load_table(name) keep working tables by name within the session''s working_table_bytes (never released, never cited). Each emit returns output metadata and the tool result lists output_ids. print() is diagnostics only. Results: OK; SCRIPT_ERROR with error_type, line, field (e.g. a missing column) and traceback: fix the code and rerun (earlier variables remain); TIMEOUT (the execution was interrupted, the session remains); INSUFFICIENT_INPUT_DATA after saniti.insufficient_data(request, range_id, value, unit, reason): revise the DataNeedSpec (for example more history). No network, database, subprocess or writes outside intermediate_path(name). Named calendar-period returns (YTD, month, quarter, year, a comparable calendar period) use period_return(request, range_id, value_column=''close''): one row per entity with base_date, base_value (the last valid value strictly before the range start), end_date, end_value (the last valid value on or before the range end), return_decimal, return_pct (full precision) and calculation_status (COMPLETE, NO_PRIOR_CLOSE, NO_END_VALUE, INVALID_BASE_VALUE, INSUFFICIENT_INPUT_DATA, DUPLICATE_BOUNDARY_OBSERVATION); it needs history_buffer 1 TRADING_OBSERVATIONS on the request. Event study: event_study(request, event, outcome, horizon, range_id=None, overlap_policy=''NON_OVERLAPPING'', baseline=''ALL_ELIGIBLE'', min_events=None, holdout_start=None, outcome_unit=None, name=None) measures the outcome after an event against a baseline. event is a condition expression over the request''s columns, per entity and past values only (+ - * / **, comparisons, & | ~, abs log exp sqrt sign min max where, lag(x, k), rolling_sum(x, n), rolling_mean(x, n)), e.g. ''close / lag(close, 1) - 1 <= -0.05''; outcome is {''forward_return'': ''<price column>''} (add ''request'': ''<data_request_id>'' when the price is in another request); horizon counts observations; the request needs one row per entity and date. NON_OVERLAPPING keeps an entity''s next event only a horizon after the last one; ALL_ELIGIBLE compares with every row, NON_EVENT with the rows without the event; holdout_start adds IN_SAMPLE and OUT_OF_SAMPLE rows. It emits <name> (one row per segment: event_count, event_dates, effective_event_dates, mean, median, hit_rate, baseline_count, baseline_mean, baseline_median, delta_mean, delta_ci_low, delta_ci_high, delta_p_value with dates as clusters, censored_count, overlapping_dropped, meets_min_events), <name>_events (date, entity, outcome), <name>_baseline and <name>_flow (rows_in_window, condition_unknown, condition_true = the qualifying events, censored, overlapping_dropped, used; condition_true = censored + overlapping_dropped + used): quote each count from <name>_flow, never derive it; never overwrite or re-emit them. Backtest: backtest(request, frame, signal, exit_signal=None, stop=None, target=None, max_hold=None, fee=None, unit=None, prices=None, range_id=None, name=None) simulates long trades of a stated rule on the bundle prices: signal (and exit_signal) are boolean columns of your frame, True on the bar whose close triggers the order (filled at the next open); stop and target are fractions of the entry price; only bars inside the approved ranges trade (warm-up rows feed indicators). Use only the exit rules the user or the script states. It emits <name>_trades and <name>_summary (signals, trades, win_rate, mean and median return, average win and loss, realized_reward_risk, profit_factor, cumulative_return, max_drawdown, bars_in_period, bars_buffer): quote them, never overwrite or re-emit them.')
) AS next(name, from_version, version, input_schema, purpose)
  ON previous.tool_name = next.name AND previous.version = next.from_version;

DO $verify$
BEGIN
    IF (SELECT count(*) FROM public."Tool_Catalog" WHERE NOT is_active AND ((tool_name = 'run_python' AND version = 'v6'))) <> 1 THEN
        RAISE EXCEPTION 'The M119 working tables tool versions were not registered';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public."Tool_Catalog" WHERE tool_name = 'run_python' AND version = 'v6' AND purpose::text LIKE '%save_table%') THEN
        RAISE EXCEPTION 'The M119 working tables contracts are not in the registered rows';
    END IF;
END
$verify$;

COMMIT;
